head.script:
scwin.onpageload = function() {}
	scwin.inputVal = function(test) {
		return false;
	}   

    scwin.simulateWrapper = function(target, type, options){
        WebSquare.wUnit.getJq(target).simulate(type, options);
    }
	scwin.checkSimulate1 = function() {
		scwin.simulateWrapper('#wq_uuid_2', 'key-sequence', {
			sequence: '333.12345678901234'
		});
	}
	scwin.checkSimulate2 = function() {
		scwin.simulateWrapper('#wq_uuid_9', 'key-sequence', {
			sequence: '.12'
		});
	}
	scwin.checkSimulate3 = function() {
		scwin.simulateWrapper('#wq_uuid_12', 'key-sequence', {
			sequence: '3333'
		});
	}
	scwin.checkSimulate4 = function() {
		scwin.simulateWrapper('#wq_uuid_15', 'key-sequence', {
			sequence: '.3333'
		});
	}
	scwin.checkSimulate1 = function() {
		scwin.simulateWrapper('#wq_uuid_2', 'key-sequence', {
			sequence: '333.12345678901234'
		});
	}	
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_2').val() == '333.1234567890123';
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_9').val() == '.1';
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_12').val() == '333';
	}	
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_15').val() == '.333';
	}		
	scwin.unitTest = function() {
        //init
        WebSquare.wUnit.start();

        WebSquare.wUnit.addCommand("pause", "1000");        
        WebSquare.wUnit.addCommand("set", "scwin.checkSimulate1()");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "scwin.checkSimulate2()");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "scwin.checkSimulate3()");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "scwin.checkSimulate4()");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_15').blur()");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        //Run and stop
        WebSquare.wUnit.run();
        WebSquare.wUnit.stop();        
    }
	scwin.unitTest();
